// Safety rules: every action is classified before it runs.
//   routine   — typing, scrolling, waiting, ordinary choices
//   important — clicks, navigation, accepting terms, filling a generated password
//   sensitive — payments / deletion, submit buttons the goal didn't ask for, protected profile fields
//   blocked   — OTPs, card / bank / government ID numbers, passwords not generated by WebPilot

import { GENERATED_PASSWORD_KEY } from './planner.js';

// Money or destruction: always needs explicit approval, in every mode.
const CRITICAL = /\b(pay|payment|purchase|buy|checkout|place order|order now|delete|remove account|deactivate|close account|transfer|send money|donate|withdraw|confirm payment)\b/i;
// Final submissions: allowed automatically only when the goal asks for them.
const FINAL = /\b(submit|register|sign ?up|create (an |my )?account|join|apply|finish|complete|confirm|send|book|enrol|enroll|subscribe)\b/i;
const NAV_SAFE = /\b(next|continue|back|previous|prev|proceed to step|save (and|&) continue|go to step)\b/i;
const TERMS = /\b(terms|agree|accept|consent|privacy|policy|conditions|declare|declaration)\b/i;
const SECRET = /\b(otp|one.time|verification code|cvv|cvc|card number|credit card|debit card|atm pin|upi pin|security code|aadhaar|ssn|pan number|account number|routing|ifsc)\b/i;

const GOAL_SUBMITS = /\b(submit|sign ?up|register|create (an |a |my )?account|make (an |a )?account|apply|enrol|enroll|book|send|complete (the |my )?(registration|application|form)|join)\b/i;
const GOAL_HOLDS = /\b(don'?t|do not|without|before) submit|prepare|ready (for|to) submi|review before/i;

/** Does the user's goal itself authorize final submit / sign-up clicks? */
export const goalAuthorizesSubmit = (goal) => GOAL_SUBMITS.test(goal || '') && !GOAL_HOLDS.test(goal || '');

export function isSecretField(el) {
  if (!el) return false;
  return /^cc-|one-time-code/.test(el.autocomplete || '') || SECRET.test(el.label || '');
}

export function classify(action, el, { askKeys = [], goal = '' } = {}) {
  const label = el?.label || '';
  const text = `${label} ${action.description || ''}`;

  if (action.type === 'fill' || action.type === 'select') {
    if (isSecretField(el)) return { level: 'blocked', reason: 'WebPilot never types OTPs, card, bank or ID numbers — it will ask you instead' };
    if (el?.inputType === 'password') {
      if (action.profileKey !== GENERATED_PASSWORD_KEY) return { level: 'blocked', reason: 'only a WebPilot-generated password can be typed into password fields' };
      return { level: 'important', reason: 'fills a new secure password (shown to you)' };
    }
    if (action.profileKey && askKeys.includes(action.profileKey)) {
      return { level: 'sensitive', reason: `uses protected profile field “${action.profileKey}”` };
    }
    return { level: action.sensitive ? 'sensitive' : 'routine', reason: action.sensitive ? 'marked sensitive by the planner' : '' };
  }

  if (action.type === 'click' || action.type === 'press') {
    if (CRITICAL.test(label) || (action.sensitive && CRITICAL.test(text))) {
      return { level: 'sensitive', reason: 'payment, purchase or deletion' };
    }
    const isFinal = (FINAL.test(label) && !NAV_SAFE.test(label)) || action.sensitive;
    if (isFinal && action.type === 'click') {
      return goalAuthorizesSubmit(goal)
        ? { level: 'important', reason: 'final submit — your goal asked for it' }
        : { level: 'sensitive', reason: 'final submit that your goal did not ask for' };
    }
    return { level: action.type === 'press' ? 'routine' : 'important', reason: action.type === 'press' ? '' : 'clicks a button or link' };
  }

  if (action.type === 'check' || action.type === 'uncheck') {
    if (TERMS.test(label)) return { level: 'important', reason: 'accepts terms or a declaration' };
    return { level: 'routine', reason: '' };
  }

  if (action.type === 'navigate') return { level: 'important', reason: `opens ${action.url}` };
  if (action.type === 'back') return { level: 'important', reason: 'goes back a page' };
  return { level: 'routine', reason: '' }; // scroll, wait, media, ask_user
}

/** Does this mode require the user to approve an action of this level? */
export function needsApproval(mode, level) {
  if (mode === 'step') return true;
  if (mode === 'review') return level !== 'routine';
  return level === 'sensitive'; // Full Auto still never pays or deletes on its own
}
